<!doctype html><html><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#292524}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border-bottom:1px solid #d6d3d1;padding:10px;text-align:left}th{text-transform:uppercase;font-size:11px;letter-spacing:.08em}tfoot td{font-weight:bold}</style></head><body><h1>HotelHub</h1><p>Invoice {{ $invoice->invoice_number }}</p><p>Reservation {{ $invoice->reservation->reservation_number }} · Room {{ $invoice->reservation->room->room_number }}</p><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>${{ number_format($item->unit_price, 2) }}</td><td>${{ number_format($item->total, 2) }}</td></tr>@endforeach</tbody><tfoot><tr><td colspan="3">Total</td><td>${{ number_format($invoice->total, 2) }}</td></tr><tr><td colspan="3">Balance</td><td>${{ number_format($invoice->balance, 2) }}</td></tr></tfoot></table></body></html>